1	import { useQuery, useMutation, useQueryClient } from "@tanstack/react-query";
2	import { supabase } from "@/integrations/supabase/client";
3	import { useAuth } from "@/hooks/useAuth";
4	import { toast } from "sonner";
5	
6	export type HiringStage = "applied" | "screened" | "interview" | "offer" | "hired" | "rejected";
7	
8	export const STAGE_ORDER: HiringStage[] = ["applied", "screened", "interview", "offer", "hired"];
9	
10	export interface CandidateStage {
11	  id: string;
12	  resume_id: string;
13	  job_id: string;
14	  stage: HiringStage;
15	  updated_at: string;
16	}
17	
18	export function useStages(jobId: string | null) {
19	  return useQuery({
20	    queryKey: ["candidate-stages", jobId],
21	    queryFn: async (): Promise<CandidateStage[]> => {
22	      if (!jobId) return [];
23	      try {
24	        const { data, error } = await (supabase as any)
25	          .from("candidate_stages")
26	          .select("id, resume_id, job_id, stage, updated_at")
27	          .eq("job_id", jobId);
28	        if (error) {
29	          // Graceful fallback if table doesn't exist (migration not applied)
30	          if (error.message?.includes("schema cache") || error.message?.includes("does not exist") || error.code === "42P01") {
31	            return [];
32	          }
33	          throw error;
34	        }
35	        return (data ?? []) as CandidateStage[];
36	      } catch (err: any) {
37	        if (err?.message?.includes("schema cache") || err?.message?.includes("does not exist")) {
38	          return [];
39	        }
40	        throw err;
41	      }
42	    },
43	    enabled: !!jobId,
44	    retry: false,
45	  });
46	}
47	
48	export function useUpdateStage() {
49	  const queryClient = useQueryClient();
50	  const { user } = useAuth();
51	
52	  return useMutation({
53	    mutationFn: async ({
54	      resumeId,
55	      jobId,
56	      newStage,
57	      currentStage,
58	    }: {
59	      resumeId: string;
60	      jobId: string;
61	      newStage: HiringStage;
62	      currentStage?: HiringStage | null;
63	    }) => {
64	      const { error: upsertError } = await (supabase as any)
65	        .from("candidate_stages")
66	        .upsert(
67	          {
68	            resume_id: resumeId,
69	            job_id: jobId,
70	            stage: newStage,
71	            updated_at: new Date().toISOString(),
72	            updated_by: user?.id,
73	          },
74	          { onConflict: "resume_id,job_id" }
75	        );
76	      if (upsertError) throw upsertError;
77	
78	      // Log transition (non-critical, don't block on failure)
79	      try {
80	        await (supabase as any)
81	          .from("stage_history")
82	          .insert({
83	            resume_id: resumeId,
84	            job_id: jobId,
85	            from_stage: currentStage || null,
86	            to_stage: newStage,
87	            changed_by: user?.id,
88	          });
89	      } catch { /* history logging is non-critical */ }
90	    },
91	    onMutate: async (variables) => {
92	      await queryClient.cancelQueries({ queryKey: ["candidate-stages", variables.jobId] });
93	      const previous = queryClient.getQueryData<CandidateStage[]>(["candidate-stages", variables.jobId]);
94	      queryClient.setQueryData<CandidateStage[]>(["candidate-stages", variables.jobId], (old) => {
95	        const entry: CandidateStage = { id: "optimistic", resume_id: variables.resumeId, job_id: variables.jobId, stage: variables.newStage, updated_at: new Date().toISOString() };
96	        if (!old) return [entry];
97	        const exists = old.find((s) => s.resume_id === variables.resumeId);
98	        if (exists) return old.map((s) => s.resume_id === variables.resumeId ? { ...s, stage: variables.newStage, updated_at: new Date().toISOString() } : s);
99	        return [...old, entry];
100	      });
101	      return { previous };
102	    },
103	    onSuccess: (_, variables) => {
104	      queryClient.invalidateQueries({ queryKey: ["candidate-stages", variables.jobId] });
105	      toast.success("Stage updated");
106	    },
107	    onError: (error: Error, variables, context) => {
108	      if (context?.previous) {
109	        queryClient.setQueryData(["candidate-stages", variables.jobId], context.previous);
110	      }
111	      if (error.message?.includes("schema cache") || error.message?.includes("does not exist")) {
112	        toast.error("Stage tracking requires database migration. Run: supabase db push");
113	      } else {
114	        toast.error(error.message || "Failed to update stage");
115	      }
116	    },
117	  });
118	}
119	
120	export function useStageSummary(jobId: string | null) {
121	  const { data: stages } = useStages(jobId);
122	
123	  const summary: Record<HiringStage, number> = {
124	    applied: 0, screened: 0, interview: 0, offer: 0, hired: 0, rejected: 0,
125	  };
126	
127	  if (stages) {
128	    stages.forEach((s) => {
129	      if (summary[s.stage] !== undefined) {
130	        summary[s.stage]++;
131	      }
132	    });
133	  }
134	
135	  return summary;
136	}
